static int load_topic_from_file(const char *topic, knowledge_topic_t *data)
{
    char filepath[256];
    cJSON *root;
    cJSON *cards_array;
    cJSON *card_obj;
    cJSON *item;
    char *json_buffer;
    int fd;
    int ret;
    int file_size;

    get_topic_file_path(topic, filepath, sizeof(filepath));

    /* 读取文件 */

    fd = open(filepath, O_RDONLY);
    if (fd < 0)
    {
        /* 文件不存在，不是错误 */

        return -ENOENT;
    }

    /* 获取文件大小 */

    file_size = lseek(fd, 0, SEEK_END);
    lseek(fd, 0, SEEK_SET);

    if (file_size <= 0 || file_size > 65536)
    {
        close(fd);
        return -EINVAL;
    }

    /* 分配缓冲区 */

    json_buffer = malloc(file_size + 1);
    if (json_buffer == NULL)
    {
        close(fd);
        return -ENOMEM;
    }

    /* 读取内容 */

    ret = read(fd, json_buffer, file_size);
    close(fd);

    if (ret != file_size)
    {
        free(json_buffer);
        return -EIO;
    }

    json_buffer[file_size] = '\0';

    /* 解析 JSON */

    root = cJSON_Parse(json_buffer);
    free(json_buffer);

    if (root == NULL)
    {
        fprintf(stderr, "ERROR: Failed to parse JSON from %s\n", filepath);
        return -EINVAL;
    }

